using System.Text;

namespace Scarlet.OpenPgp.Tests.Fixtures
{
    /// <summary>
    /// v6 (RFC 9580) keys and signatures made by OpenPGP.js 6.3.2 - an independent implementation -
    /// so v6 support is checked against a real producer, not only against the RFC's own vectors and
    /// certificates assembled by hand. Generated by <c>TestAssets/openpgpjs-v6/generate.mjs</c>.
    /// </summary>
    public class OpenPgpJsInteropTests
    {
        private const string Folder = "TestAssets/openpgpjs-v6/";

        /// <summary>After the signatures were made (2026-01-02); none of the keys expire.</summary>
        private static readonly DateTimeOffset Now = new DateTimeOffset(2026, 6, 1, 0, 0, 0, TimeSpan.Zero);

        public static TheoryData<string, string, string> Variants => new()
        {
            // folder, signing key fingerprint, primary key fingerprint
            { "v6-ed25519", "0CB5CF5501B8840B4A2B35D3307282E5B6E859DADF3242697F47DCB02B67019F", "0CB5CF5501B8840B4A2B35D3307282E5B6E859DADF3242697F47DCB02B67019F" },
            { "v6-ed448", "F1AD8CCD6A7B98B6281056D2F3EE5BBEA215B3B90DCFB6B530CDD26C7A3039A8", "F1AD8CCD6A7B98B6281056D2F3EE5BBEA215B3B90DCFB6B530CDD26C7A3039A8" },
            { "v6-ed25519-signing-subkey", "6B88C7304BF790741E1C94F749EA7D1401B583F6360CECC0F7E41A10E5278970", "997C3A2FFA39828FDA5CB9EE5FC958C253A23BC8386C9514CA5CE4F0BFA42F90" },
            { "v6-rsa3072", "BBD38D3E9FEEFE1077AE3C2DB3E934D992473A1A7FC3C4BE1A3AB3F789CA10AF", "BBD38D3E9FEEFE1077AE3C2DB3E934D992473A1A7FC3C4BE1A3AB3F789CA10AF" },
            { "v6-ecdsa-nistp256", "C00E2B6CD91BC69AC119B43DFA064DED19E5719C1FEC010067896E83FFC6B393", "C00E2B6CD91BC69AC119B43DFA064DED19E5719C1FEC010067896E83FFC6B393" },
        };

        private static byte[] Bytes(string variant, string file) => File.ReadAllBytes(Folder + variant + "/" + file);

        [Theory]
        [MemberData(nameof(Variants))]
        public void DetachedSignatures_FromOpenPgpJs_ShouldVerify(string variant, string signer, string primary)
        {
            // Arrange
            OpenPgpKeyRing keyRing = OpenPgpKeyRing.Parse(Bytes(variant, "public-key.asc"));
            byte[] data = Bytes(variant, "data.txt");

            // Act
            VerificationResult binary = OpenPgpVerifier.VerifyDetached(data, Bytes(variant, "data.txt.sig"), keyRing, Now);
            VerificationResult textMode = OpenPgpVerifier.VerifyDetached(data, Bytes(variant, "data.txt.textmode.asc"), keyRing, Now);

            // Assert
            foreach (VerificationResult result in new[] { binary, textMode })
            {
                Assert.True(result.IsValid, variant + ": " + result);
                Assert.Equal(signer, result.SignerFingerprint);
                Assert.Equal(primary, result.PrimaryKeyFingerprint);
            }

            Assert.Equal(6, Assert.Single(keyRing.Certificates).PrimaryKey.Version);
        }

        [Theory]
        [MemberData(nameof(Variants))]
        public void ClearsignedMessage_FromOpenPgpJs_ShouldVerifyAndReturnTheSignedText(string variant, string signer, string primary)
        {
            // Arrange
            OpenPgpKeyRing keyRing = OpenPgpKeyRing.Parse(Bytes(variant, "public-key.asc"));
            string message = Encoding.UTF8.GetString(Bytes(variant, "data.txt.clearsign.asc"));

            // The signed text in canonical form: every line of data.txt with trailing whitespace
            // stripped, joined by CRLF. data.txt ends with a line break, and OpenPGP.js signs it, so
            // the canonical text ends with CRLF too.
            string expected = string.Join("\r\n", Encoding.UTF8.GetString(Bytes(variant, "data.txt")).Split('\n').Select(l => l.TrimEnd(' ', '\t')));

            // Act
            VerificationResult result = OpenPgpVerifier.VerifyClearsign(message, keyRing, Now);

            // Assert
            Assert.True(result.IsValid, variant + ": " + result);
            Assert.Equal(signer, result.SignerFingerprint);
            Assert.Equal(primary, result.PrimaryKeyFingerprint);
            Assert.Equal(expected, result.SignedText);
        }

        [Theory]
        [MemberData(nameof(Variants))]
        public void DetachedSignature_FromOpenPgpJs_OverTamperedData_ShouldBeRejected(string variant, string signer, string primary)
        {
            // Arrange
            OpenPgpKeyRing keyRing = OpenPgpKeyRing.Parse(Bytes(variant, "public-key.asc"));
            byte[] tampered = Bytes(variant, "data.txt");
            tampered[0] ^= 0x01;

            // Act
            VerificationResult result = OpenPgpVerifier.VerifyDetached(tampered, Bytes(variant, "data.txt.sig"), keyRing, Now);

            // Assert
            Assert.Equal(VerificationStatus.BadSignature, result.Status);
            Assert.Equal(signer, result.SignerFingerprint);
            Assert.Equal(primary, result.PrimaryKeyFingerprint);
        }
    }
}
